/* DAYMARK: associative imagery and a coherent goal → action → journal → progress route. */
const SUPPORT_SYMBOLS={food:'🍽',mealplan:'🥗',protein:'🥚',cook:'🍳',vegetables:'🥬',water:'💧',breakfast:'🥣',fruit:'🍎',mindful:'🍴',move:'🏃',walk:'👟',strength:'🏋',mobility:'🧘',breaks:'🚶',cycle:'🚲',dance:'💃',swim:'🏊',stretch:'🤸',recovery:'🛋',sleep:'🌙',bedtime:'🛏',screen:'📵',checkin:'💬',meditate:'🎧',breath:'🌬',journal:'📝',focus:'🎯',study:'📚',language:'🗣',read:'📖',work:'✅',create:'🎬',planDay:'🗓',practice:'🎨',pause:'⏱',budget:'💳',home:'🧺',connect:'🤝',outside:'🌳',hobby:'🎸',nature:'🌲',social:'💌',custom:'✍'};
const SUPPORT_PHOTOS={food:'food-day-v2.webp',mealplan:'food-day-v2.webp',cook:'food-day-v2.webp',vegetables:'food-day-v2.webp',move:'walk-park-v2.webp',walk:'walk-park-v2.webp',outside:'walk-park-v2.webp',strength:'training-gear-v2.webp',mobility:'training-legs-v2.webp',sleep:'rest-evening-v2.webp',bedtime:'rest-evening-v2.webp',recovery:'rest-evening-v2.webp'};
const SUPPORT_ROUTES={meals:'food',minutes:'move',steps:'move',water:'food',sleep:'sleep',checkin:'coach',protein:'food',strength:'move',mobility:'move'};
function supportVisual(id,small=false){const photo=small?null:SUPPORT_PHOTOS[id];return '<span class="support-visual '+(small?'small':'')+(photo?' has-photo':'')+'" aria-hidden="true">'+(photo?'<img src="assets/'+photo+'" alt="" loading="lazy">':'<span>'+SUPPORT_SYMBOLS[id]+'</span>')+'</span>';}
function supportProgress(x){return Math.round(Math.min(1,Math.max(0,(x.value||0)/x.target))*100);}
function supportReadout(x){if(!x.planned)return 'Сьогодні день без цієї опори';if(x.needsPlan)return 'Потрібен орієнтир білка у плані харчування';if(x.value===null)return x.automatic?'Чекає на запис у щоденнику':'Чекає на твій запис';return x.done?'Зроблено: '+num(x.value,1)+' '+x.unit+' · ціль '+num(x.target,1):num(x.value,1)+' із '+num(x.target,1)+' '+x.unit;}
function supportSource(x){return x.automatic?'Оновлюється зі щоденника '+({food:'їжі',move:'руху',sleep:'сну',coach:'стану'}[SUPPORT_ROUTES[x.def.auto]]||''):'Ти відзначаєш вручну';}
supportRows=function(g,compact=false){return g.habits.map(id=>{const x=supportStatus(g,id);return '<button class="support-tile '+x.def.group+(x.done?' done':'')+(x.planned?'':' off-day')+'" data-action="support-open" data-id="'+id+'" aria-label="'+esc(x.label)+'. '+esc(supportReadout(x))+'. Відкрити"><span class="support-tile-image">'+supportVisual(id)+'</span><span class="support-tile-body"><span class="support-tile-top"><strong>'+esc(x.label)+'</strong><b class="support-state">'+(x.done?'Готово ✓':x.planned?'Мій крок':'Відпочинок')+'</b></span><span class="support-readout">'+esc(supportReadout(x))+'</span><span class="support-meter" role="img" aria-label="Виконано '+supportProgress(x)+' відсотків"><i style="width:'+supportProgress(x)+'%"></i></span><small>'+supportSource(x)+' <b>↗</b></small></span></button>';}).join('');};
function supportsToday(g){const xs=g.habits.map(id=>supportStatus(g,id)),planned=xs.filter(x=>x.planned),done=planned.filter(x=>x.done);return {xs,planned,done,pct:planned.length?Math.round(done.length/planned.length*100):0};}
smartHabitPanel=function(){const g=goal(),s=supportsToday(g);return '<section class="supports-home-v3"><div class="supports-home-head"><div><span>МІЙ ПЛАН / СЬОГОДНІ</span><h2>Мої опори</h2><p>Обрані дії під твою ціль. Записи з інших розділів зʼявляються тут.</p></div><button data-view="supports" aria-label="Відкрити мої опори"><b>'+s.done.length+' із '+s.planned.length+'</b><small>сьогодні ↗</small></button></div><div class="support-tiles">'+supportRows(g,true)+'</div><button class="support-customize" data-action="supports-settings">Змінити мої опори <b>↗</b></button><div class="minimum-card"><h3>Якщо день складний</h3><p>Твій мінімум: '+esc(g.minimum)+'</p><button class="text-btn" data-action="minimum">Відзначити цей крок ↗</button></div></section>';};
function supportWeek(g){return Array.from({length:7},(_,i)=>{const d=offset(selectedDate,i-6),a=g.habits.map(id=>supportStatus(g,id,d)).filter(x=>x.planned),n=a.filter(x=>x.done).length,h=a.length?Math.max(8,Math.round(n/a.length*100)):8;return '<div class="support-week-day" title="'+esc(fdate(d))+': '+n+' із '+a.length+'"><span class="support-week-bar"><i style="height:'+h+'%"></i></span><b>'+n+'/'+a.length+'</b><small>'+new Intl.DateTimeFormat('uk-UA',{weekday:'short',timeZone:'UTC'}).format(dt(d))+'</small></div>';}).join('');}
supportsView=function(){const g=goal(),s=supportsToday(g),t=GOAL_TEMPLATES[g.kind]||GOAL_TEMPLATES.custom;return pageTop('Мої опори','ДІЇ ПІД МОЮ ЦІЛЬ / '+esc(g.title),dateControl())+'<section class="supports-dashboard"><div class="supports-goal-visual"><img src="assets/'+({lose:'training-legs-v2.webp',gain:'food-day-v2.webp',muscle:'training-gear-v2.webp',sleep:'rest-evening-v2.webp',walking:'walk-park-v2.webp'}[g.kind]||'walk-park-v2.webp')+'" alt="" loading="lazy"></div><div class="supports-goal-content"><span>МОЯ ЦІЛЬ · '+esc(t.name)+'</span><h2>'+esc(g.title)+'</h2><p>'+esc(t.line)+'</p><div class="supports-donut" style="--pct:'+s.pct+'"><strong>'+s.done.length+'<small> / '+s.planned.length+'</small></strong><span>опор виконано<br>сьогодні</span></div></div></section><div class="supports-route"><div><b>01</b><strong>Обери свої дії</strong><small>Із каталогу або власну</small></div><div><b>02</b><strong>Записуй свій день</strong><small>Їжа, рух, сон чи вручну</small></div><div><b>03</b><strong>Бачиш прогрес</strong><small>Тут і в календарі</small></div></div><div class="supports-list-head"><div><span>ТВІЙ НАБІР / '+g.habits.length+' ДІЙ</span><h2>Сьогоднішні кроки</h2><p>Натисни на опору, щоб внести дію або відкрити повʼязаний щоденник.</p></div><button data-action="supports-settings">Налаштувати ↗</button></div><div class="support-tiles supports-tiles-full">'+supportRows(g)+'</div>'+(s.planned.length&&s.done.length===s.planned.length?'<button class="support-victory" data-action="quick-mark">Усі сьогоднішні опори є · закреслити день у календарі ↗</button>':'')+'<section class="support-week-panel"><span>ОСТАННІ 7 ДНІВ</span><h2>Як складалися маленькі кроки</h2><div class="supports-week-v3">'+supportWeek(g)+'</div><p>Показано за нинішнім набором опор. Позначки в календарі зберігаються окремо.</p></section><div class="supports-next"><button data-action="supports-settings">＋ Додати або змінити опори</button><button data-view="goals">Усі мої цілі ↗</button></div><div class="minimum-card support-minimum"><h3>План на складний день</h3><p>'+esc(g.minimum)+'</p><button data-action="minimum">Відзначити маленький крок ↗</button></div>'+(t.nutrition?'<button class="support-plan-link" data-action="plan">🍽 <span><b>Орієнтир харчування</b><small>Калорії та БЖВ для твоєї цілі</small></span> ↗</button>':'');};
supportsSettings=function(reset=false){const g=goal(),t=GOAL_TEMPLATES[g.kind]||GOAL_TEMPLATES.custom;if(!supportsDraft||reset)supportsDraft={ids:[...(reset?t.habits:g.habits)],rules:reset?{}:structuredClone(g.supportRules||{})};const draft=supportsDraft;const groups=Object.entries(SUPPORT_GROUPS).map(([group,name])=>{const entries=Object.entries(SUPPORT_DEFINITIONS).filter(([,d])=>d.group===group);return '<details class="support-catalog-group" '+(entries.some(([id])=>draft.ids.includes(id))?'open':'')+'><summary><span>'+({food:'🍽',move:'🏃',rest:'🌙',focus:'🎯',life:'🌿'}[group])+'</span><strong>'+name+'</strong><small>'+entries.filter(([id])=>draft.ids.includes(id)).length+' обрано</small></summary><div class="support-catalog-grid">'+entries.map(([id,d])=>{const x=supportRule({...g,supportRules:draft.rules},id);return '<div class="support-catalog-item">'+supportVisual(id,true)+'<label class="support-catalog-check"><input type="checkbox" name="support" value="'+id+'" '+(draft.ids.includes(id)?'checked':'')+'><span><b>'+d.name+'</b><small>'+d.sub+'</small></span></label><details class="support-catalog-config"><summary>Мій крок · '+num(x.target,1)+' '+d.unit+' ↗</summary><div class="form-pair"><label class="form-label">Скільки, '+d.unit+'<input type="number" name="target_'+id+'" min="1" max="100000" step="any" value="'+x.target+'"></label><label class="form-label">Коли?<select name="schedule_'+id+'">'+[['daily','Щодня'],['weekdays','Пн–Пт'],['three','Пн, Ср, Пт'],['weekends','Сб–Нд']].map(([k,n])=>'<option value="'+k+'" '+(supportScheduleName(x.days)===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><label class="form-label">Моя назва<input name="label_'+id+'" maxlength="80" value="'+esc(x.label)+'"></label>'+(id==='protein'?'<label class="recipe-checkbox"><input name="follow_protein" type="checkbox" '+(x.followPlan?'checked':'')+'>Брати орієнтир білка з мого плану</label>':'')+(d.auto?'<label class="recipe-checkbox"><input type="checkbox" name="auto_'+id+'" '+(x.automatic?'checked':'')+'>Автоматично зі щоденника</label>':'')+'</details></div>';}).join('')+'</div></details>';}).join('');openModal('МОЇ ОПОРИ / НАЛАШТУВАННЯ','<div class="support-config-head"><span>ПІД ЦІЛЬ: '+esc(g.title)+'</span><h2>Твої дії.<br>Твій ритм.</h2><p>Обери кілька опор. Їжу, рух і сон можна повʼязати зі щоденниками — не доведеться ставити позначку двічі. Власні дії позначай вручну.</p><div><b>'+draft.ids.length+'</b> уже у твоєму наборі</div></div><form id="supportsForm">'+groups+'<label class="form-label support-minimum-input">Мій мінімум на складний день<input name="minimum" maxlength="180" value="'+esc(g.minimum)+'" required><small>Це твоя особиста маленька дія.</small></label><p class="form-error" id="supportsError" role="alert"></p><button class="btn blue full">Зберегти мої опори</button><button class="text-btn full" type="button" data-action="supports-reset">Повернути набір для цієї цілі</button></form>');};
const visualGoalCard=goalCard;
goalCard=function(g){const pct=Math.round(completed(g)/total(g)*100),kind=GOAL_TEMPLATES[g.kind]||GOAL_TEMPLATES.custom,photo={lose:'training-legs-v2.webp',gain:'food-day-v2.webp',muscle:'training-gear-v2.webp',sleep:'rest-evening-v2.webp',walking:'walk-park-v2.webp'}[g.kind]||'walk-park-v2.webp';return '<section class="goal-card-v3 '+(g.id===state.active?'active':'')+'"><div class="goal-card-photo"><img src="assets/'+photo+'" alt="" loading="lazy"><span>'+esc(kind.name)+'</span></div><div class="goal-card-content"><div class="goal-card-ring" style="--pct:'+pct+'" aria-label="'+pct+' відсотків днів відзначено"><b>'+pct+'<small>%</small></b></div><h2>'+esc(g.title)+'</h2><p>'+fdate(g.start)+' — '+fdate(g.end)+'</p><div class="goal-card-facts"><span><b>'+completed(g)+'</b> днів відзначено</span><span><b>'+total(g)+'</b> днів у цілі</span></div><button data-action="choose-goal" data-id="'+g.id+'">Відкрити мій календар ↗</button></div></section>';};
const visualTrainingStudio=trainingStudio;
trainingStudio=function(){return visualTrainingStudio().replace(/(<button class="training-card [^"]+" data-action="training-open" data-id="([^"]+)">[\s\S]*?)<span class="training-card-art" aria-hidden="true">[^<]*<\/span>/g,(_,before,id)=>{const p=TRAINING_PLANS.find(x=>x.id===id),name=p?.name||'',file=p?.place==='outdoor'?'walk-park-v2.webp':/ног|сідниц|присід|нижн/i.test(name)?'training-legs-v2.webp':/гантел|сил|резин|рук|спин|зал/i.test(name)?'training-gear-v2.webp':'movement-editorial.png';return before+'<span class="training-card-photo" aria-hidden="true"><img src="assets/'+file+'" alt="" loading="lazy"></span>';});};
const visualSupportsSettings=supportsSettings;
supportsSettings=function(reset=false){visualSupportsSettings(reset);const form=document.getElementById('supportsForm');if(!form)return;form.addEventListener('change',()=>{const chosen=[...form.querySelectorAll('input[name="support"]:checked')].map(x=>x.value);const total=document.querySelector('.support-config-head>div b');if(total)total.textContent=chosen.length;form.querySelectorAll('.support-catalog-group').forEach(group=>{const label=group.querySelector('summary small');if(label)label.textContent=group.querySelectorAll('input[name="support"]:checked').length+' обрано';});});};
const GOAL_SYMBOLS={lose:'👟',gain:'🍽',muscle:'🏋',form:'🏃',energy:'☀️',consistent:'✅',homefit:'🏠',walking:'🚶',sleep:'🌙',wedding:'💍',study:'📚',language:'🗣',work:'💼',blog:'🎬',read:'📖',budget:'💳',routine:'🗓',custom:'✍'};
const GOAL_PHOTOS={lose:'training-legs-v2.webp',gain:'food-day-v2.webp',muscle:'training-gear-v2.webp',form:'walk-park-v2.webp',homefit:'training-legs-v2.webp',walking:'walk-park-v2.webp',sleep:'rest-evening-v2.webp'};
const visualOnboard=onboardSmartView;
onboardSmartView=function(){visualOnboard();document.querySelectorAll('.goal-choice').forEach(card=>{const id=card.dataset.id,mark=card.querySelector(':scope > span');if(mark){mark.textContent=GOAL_SYMBOLS[id]||'🎯';if(GOAL_PHOTOS[id]){mark.classList.add('goal-choice-photo');mark.style.backgroundImage='url(assets/'+GOAL_PHOTOS[id]+')';}}});document.querySelectorAll('.onboard-support').forEach(row=>{const input=row.querySelector('input[name="habit"]');if(input)row.dataset.symbol=SUPPORT_SYMBOLS[input.value]||'🎯';});};
function trainingPhoto(p){const byId={'home-start':'movement-editorial.png','home-all':'home-lunge-v2.webp','home-legs':'training-legs-v2.webp','home-upper':'home-band-v2.webp','home-dumbbell':'training-gear-v2.webp','home-bands':'home-band-v2.webp','gym-first':'gym-cable-v2.webp','gym-full':'training-gear-v2.webp','gym-legs':'training-legs-v2.webp','gym-back':'gym-cable-v2.webp'};if(byId[p.id])return byId[p.id];if(p.place==='outdoor')return 'walk-park-v2.webp';if(p.place==='gym')return /ног|сідниц|присід/i.test(p.name)?'training-legs-v2.webp':'gym-cable-v2.webp';if(/ног|сідниц|присід/i.test(p.name))return 'training-legs-v2.webp';if(/резин|естрич|еспандер/i.test(p.name))return 'home-band-v2.webp';if(/гантел|сил/i.test(p.name))return 'training-gear-v2.webp';return 'home-lunge-v2.webp';}
const variedTrainingStudio=trainingStudio;
trainingStudio=function(){return variedTrainingStudio().replace(/(<button class="training-card [^"]+" data-action="training-open" data-id="([^"]+)">[\s\S]*?<img src="assets\/)[^"]+/g,(_,prefix,id)=>{const p=TRAINING_PLANS.find(x=>x.id===id);return prefix+(p?trainingPhoto(p):'movement-editorial.png');});};
const visualTrainingOpen=trainingOpen;
trainingOpen=function(id){visualTrainingOpen(id);const p=TRAINING_PLANS.find(x=>x.id===id),head=document.querySelector('#modalBody .training-detail-head');if(p&&head)head.insertAdjacentHTML('afterbegin','<img class="training-detail-photo" src="assets/'+trainingPhoto(p)+'" alt="" loading="lazy">');};
const visualSupportOpen=supportOpen;
supportOpen=function(id){visualSupportOpen(id);if(id==='meditate'){const form=document.getElementById('supportLogForm');if(form)form.insertAdjacentHTML('beforebegin','<button class="support-meditation-link" data-view="wellbeing">🎧 Відкрити медитації та афірмації ↗<small>Після сеансу відзнач цю опору тут вручну.</small></button>');}};
